const { seg, lerp, eo, eio } = kit;
const CROWD = [
  [{ outfit: 'dress', hair: 'long', hat: 'coif', color: '#8FA86E', shade: '#748A57' }, 300, 820, 1.5],
  [{ age: 'old', outfit: 'peasant', facial: 'longbeard', hairColor: 'grey', hair: 'balding' }, 620, 820, 1.5],
  [{ outfit: 'robe', hair: 'tonsure' }, 960, 820, 1.5],
  [{ age: 'child', outfit: 'tunic', hair: 'curly', hairColor: 'black' }, 1240, 840, 1.5],
  [{ outfit: 'tunic', hair: 'short', hat: 'straw', facial: 'beard', hairColor: 'red' }, 1560, 820, 1.5],
  [{ outfit: 'peasant', hair: 'short', facial: 'stubble' }, 470, 1080, 1.95],
  [{ outfit: 'dress', hair: 'bun', hairColor: 'black', color: '#D98C7A', shade: '#B9705F' }, 1100, 1090, 1.95],
  [{ outfit: 'guard' }, 1720, 1080, 1.95],
];
kit.scene('crowd', {
  init(kit) {
    const M = W.MOODS.stoneBlue;
    kit.stage.append(kit.h('<div class="ground"><div class="layer crowd-cam"><svg class="art" viewBox="0 0 1920 1080">' + W.bg.stoneRoom(M, { seed: 12, floorY: 700, flagstones: true }) + W.glow(1700, 300, 700, '#E8EEF2', 0.4) +
      CROWD.map((c, i) => W.person('crowd-p' + i, c[0])).join('') + '</svg></div><div class="vignette"></div></div>'));
    this.ms = CROWD.map((c, i) => W.bindPerson(kit.stage, 'crowd-p' + i));
    this.cam = kit.stage.querySelector('.crowd-cam');
  },
  render(t) {
    this.cam.style.transformOrigin = '960px 600px';
    this.cam.style.transform = 'translateX(' + lerp(20, -20, t / 4).toFixed(1) + 'px) scale(' + lerp(1.02, 1.07, eio(seg(t, 0, 4))).toFixed(4) + ')';
    // takes ripple along the faces: worried on 'began', flinch on 'downward', eyes shut near the end
    this.ms.forEach((m, i) => {
      const c = CROWD[i], k = (i % 5) * 0.11 + (i > 4 ? 0.05 : 0);
      const t1 = 0.95 + k, t2 = 2.06 + k * 0.6, t3 = 3.1 + k;
      const expr = t < t1 ? 'neutral' : t < t2 ? 'worried' : t < t3 ? 'surprised' : (i % 2 ? 'sleep' : 'sad');
      const sq = Math.max(W.take(t, t1), W.take(t, t2));
      W.posePerson(m, { x: c[1] + W.tremble(t, t2, t2 + 0.4), y: c[2], s: c[3], expr, sq, head: lerp(0, -8, eio(seg(t, t2, t2 + 0.25))) + Math.sin(t * 2 + i) * 1.2, blink: W.blinkAt(t, [0.4 + i * 0.07]), a1: -8, b1: 8 });
    });
  },
});
